<span class="line"><span style="color:#E5C07B;">                context</span><span style="color:#ABB2BF;">.</span><span style="color:#E5C07B;">Features</span><span style="color:#ABB2BF;">.</span><span style="color:#61AFEF;">Set</span><span style="color:#ABB2BF;">&lt;</span><span style="color:#E5C07B;">IHttpAuthenticationFeature</span><span style="color:#ABB2BF;">&gt;(</span><span style="color:#E06C75;">authFeatures</span><span style="color:#ABB2BF;">);</span></span>
