<span class="line"><span style="color:#E5C07B;">            ctx</span><span style="color:#ABB2BF;">.</span><span style="color:#E5C07B;">ResponseBody</span><span style="color:#56B6C2;"> =</span><span style="color:#98C379;"> &quot;Not Found&quot;</span><span style="color:#ABB2BF;">;</span></span>
